-- composition of rule kernels L:optimize_unions x P:FilterPushdown (datafusion), template graft_exists
SELECT DISTINCT '0 days'::interval AS c0, make_array('a', 'b') AS c1, '1970-01-01'::date AS c2 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3)) WHERE COALESCE ((LENGTH ((SELECT STRING_AGG ('NaN'::text, ',' ORDER BY 'NaN'::text) FROM (SELECT * FROM tp WHERE EXISTS (SELECT 1 FROM (SELECT '%'::text AS c0 INTERSECT (SELECT 'a'::text AS c0 UNION (SELECT '[1,10)'::text AS c0 UNION SELECT 'x%'::text AS c0))) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT '%'::text AS c0 INTERSECT (SELECT 'a'::text AS c0 UNION (SELECT '[1,10)'::text AS c0 UNION SELECT 'x%'::text AS c0))) AS kb)) AS a3)) <> a2.c0), (a1.c0 IS DISTINCT FROM a2.c0));
-- pgfuzz:check kernel:graft_exists SELECT DISTINCT '0 days'::interval AS c0, make_array('a', 'b') AS c1, '1970-01-01'::date AS c2 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3)) WHERE COALESCE ((LENGTH ((SELECT STRING_AGG ('NaN'::text, ',' ORDER BY 'NaN'::text) FROM tp AS a3)) <> a2.c0), (a1.c0 IS DISTINCT FROM a2.c0))
